f=/Users/evisdrenova/.claude/projects/-Users-evisdrenova-conductor-workspaces-entire-brain-beijing/aa334794-9a72-4ab8-bd27-675fdda29bc9.jsonl; python3 -c "
import json
users=[]; asst_last=None
with open('$f') as fh:
    for l in fh:
        try: r=json.loads(l)
        except: continue
        t=r.get('type')
        if t=='user':
            m=r.get('message',{})
            c=m.get('content')
            txt=None
            if isinstance(c,str): txt=c
            elif isinstance(c,list):
                parts=[b.get('text','') for b in c if isinstance(b,dict) and b.get('type')=='text']
                txt=' '.join(parts)
            if txt and not txt.strip().startswith('<') and 'tool_result' not in txt[:20]:
                users.append((r.get('timestamp'), txt[:400]))
        elif t=='assistant':
            m=r.get('message',{})
            for b in m.get('content',[]):
                if isinstance(b,dict) and b.get('type')=='text' and b.get('text','').strip():
                    asst_last=(r.get('timestamp'), b['text'])
for ts,u in users[:6]:
    print('USER', ts, '::', u.replace(chr(10),' ')[:350]); print()
print('=== LAST ASSISTANT', asst_last[0] if asst_last else None)
print(asst_last[1][:2500] if asst_last else '')
"

