diff --git a/CHANGELOG.md b/CHANGELOG.md
index 5aa87499f..debf2e44a 100644
--- a/CHANGELOG.md
+++ b/CHANGELOG.md
@@ -5,6 +5,15 @@ All notable changes to `entire-brain` are recorded here. The format follows

 ## [Unreleased]

+### Fixed
+
+- `recall --evidence` no longer returns harness-injected `<system-reminder>`
+  text as `role: "user"` evidence. User-role strings and text blocks now go
+  through the same wrapper filter as the conversation reader, so reminders,
+  `Caveat:` notes and environment envelopes are skipped like system-role
+  records already were. As in conversation, user text that itself starts with
+  `<` is skipped too. Assistant text is unchanged (#565).
+
 ## [0.5.1] - 2026-11-04

 ### Fixed
diff --git a/docs/recall-evidence.md b/docs/recall-evidence.md
index 77dec28df..4910c0898 100644
--- a/docs/recall-evidence.md
+++ b/docs/recall-evidence.md
@@ -40,7 +40,11 @@ must interpret the evidence and acknowledge missing or conflicting context.
 - Supports plain text, Claude/Pi messages, Codex user/assistant events and
   response messages, simple role/content JSONL, and OpenCode message documents.
   Structured hidden reasoning, tool output, system instructions and metadata
-  are not returned as conversation text. Plain text has no role classification.
+  are not returned as conversation text. That includes user-role fields that
+  the conversation reader treats as injected wrappers, such as
+  `<system-reminder>` blocks, `Caveat:` notes and environment envelopes. The
+  filter is the same one conversation uses, so a user field that itself starts
+  with `<` is not returned either. Plain text has no role classification.
 - Malformed JSON, invalid UTF-8, unavailable files, and sources with no supported
   conversation fields yield warnings and `partial` or `unavailable` retrieval.
   Known non-conversation records are ignored. Ambiguous session identities fail
diff --git a/internal/cli/recall_evidence_source.go b/internal/cli/recall_evidence_source.go
index 16ed8b0a8..91a4c430c 100644
--- a/internal/cli/recall_evidence_source.go
+++ b/internal/cli/recall_evidence_source.go
@@ -90,11 +90,21 @@ func evidenceBlocks(text string) [][2]int {

 // Explicit schemas prevent hidden reasoning, tool output and arbitrary metadata
 // from becoming conversation evidence. String values are never normalized.
-func evidenceJSONFields(obj map[string]any, prefix string, line int) []evidenceField {
-	var fields []evidenceField
+// User-role fields go through isWrapperRequest, the predicate every other
+// request reader uses, so harness-injected text (system reminders, caveats,
+// environment envelopes) is not returned as something the user said. Evidence
+// is deliberately no stricter than the conversation reader: user text that
+// itself starts with "<" is dropped there too. skipped counts the user fields
+// withheld this way, so a session holding only those is not mistaken for
+// unsupported content.
+func evidenceJSONFields(obj map[string]any, prefix string, line int) (fields []evidenceField, skipped int) {
 	timestamp := jsonString(obj["timestamp"])
 	add := func(value any, pointer, role string) {
 		if s, ok := value.(string); ok && strings.TrimSpace(s) != "" {
+			if role == "user" && isWrapperRequest(strings.TrimSpace(s)) {
+				skipped++
+				return
+			}
 			fields = append(fields, evidenceField{s, prefix + pointer, role, timestamp, line})
 		}
 	}
@@ -154,7 +164,7 @@ func evidenceJSONFields(obj map[string]any, prefix string, line int) []evidenceF
 			}
 		}
 	}
-	return fields
+	return fields, skipped
 }

